fn is_sorted(xs: List[Int]) -> Bool
  requires len(xs) >= 0
  ensures not result or forall i in 0..len(xs) - 1: xs[i] <= xs[i + 1]
  ensures result or exists i in 0..len(xs) - 1: xs[i] > xs[i + 1]
  effects pure
  example is_sorted([1, 2, 2, 5]) == true
  example is_sorted([3, 1]) == false
  example is_sorted([]) == true
  example is_sorted([7]) == true
{
  match xs {
    [] => true
    [h, ..t] => match t {
      [] => true
      [y, ..r] => h <= y and is_sorted(t)
    }
  }
}

