fn max_of(xs: List[Int]) -> Int
  requires len(xs) >= 1
  ensures contains(xs, result)
  ensures forall x in xs: x <= result
  effects pure
  example max_of([3, 9, 1]) == 9
  example max_of([4]) == 4
{
  match xs {
    [] => 0
    [h, ..t] => match t {
      [] => h
      [_, ..r] => if h >= max_of(t) then h else max_of(t)
    }
  }
}

fn without(xs: List[Int], v: Int) -> List[Int]
  requires distinct(xs)
  requires contains(xs, v)
  ensures len(result) == len(xs) - 1
  ensures not contains(result, v)
  effects pure
  example without([3, 9, 1], 9) == [3, 1]
  example without([4], 4) == []
{
  match xs {
    [] => []
    [h, ..t] => if h == v then t else [h] ++ without(t, v)
  }
}

fn second_largest(xs: List[Int]) -> Option[Int]
  requires distinct(xs)
  ensures (len(xs) < 2 and result == None) or (len(xs) >= 2 and exists x in xs: (result == Some(x) and exists m in xs: (x < m and (forall y in xs: y <= m) and (forall y in xs: (y <= x or y >= m)))))
  effects pure
  example second_largest([3, 9, 1]) == Some(3)
  example second_largest([4]) == None
  example second_largest([]) == None
  example second_largest([5, 2]) == Some(2)
{
  match xs {
    [] => None
    [_, ..t] => match t {
      [] => None
      [_, ..r] => Some(max_of(without(xs, max_of(xs))))
    }
  }
}

